// Pure actor selection kept separate so the GNOME Shell hierarchy decision is
// covered by unit tests without requiring a running compositor.

export function selectVisualActor(delegate) {
    // Keep labels, notification badges and running indicators at native size.
    return delegate?.icon?._iconBin ?? null;
}
DOCK_FILE_custom_effects_actor_selection_js_END

# ARCHIVO: custom-effects/lens-math.js
mkdir -p -- "$stage/"'custom-effects'
cat > "$stage/"'custom-effects/lens-math.js' <<'DOCK_FILE_custom_effects_lens_math_js_END'
// Lente de ampliación estilo macOS (puro, sin dependencias de GNOME Shell).
//
// Cada icono a distancia d del cursor se amplía con s(d) = 1 + (M - 1) * nivel(d)
// (coseno elevado). El desplazamiento de su centro es la integral de (s - 1):
// así el icono bajo el cursor no se mueve, los vecinos se separan de forma
// continua y el dock «se ensancha» como en macOS, sin saltos entre iconos.

// Desplazamiento extra acumulado a distancia `distance` del cursor.
export function lensExtra(distance, radius, maxScale) {
    const k = Math.max(1, maxScale) - 1;
    if (k === 0 || radius <= 0 || distance <= 0)
        return 0;
    const m = Math.min(distance, radius);
    return k * (m / 2 + radius * Math.sin(Math.PI * m / radius) / (2 * Math.PI));
}

// Desplazamiento firmado (hacia fuera del cursor) para un centro `center`.
export function lensOffset(center, pointer, radius, maxScale) {
    const delta = center - pointer;
    return Math.sign(delta) * lensExtra(Math.abs(delta), radius, maxScale);
}
DOCK_FILE_custom_effects_lens_math_js_END

# ARCHIVO: custom-effects/magnification-math.js
mkdir -p -- "$stage/"'custom-effects'
cat > "$stage/"'custom-effects/magnification-math.js' <<'DOCK_FILE_custom_effects_magnification_math_js_END'
// Pure math kept separate so it can be tested without a running GNOME Shell.

export function clamp(value, lower, upper) {
    return Math.min(Math.max(value, lower), upper);
}

export function magnificationLevel(distance, radius) {
    if (radius <= 0 || distance >= radius)
        return 0;

    // Raised cosine: no visual corner at either the peak or its fall-off edge.
    return (Math.cos(distance * Math.PI / radius) + 1) / 2;
}

export function magnifiedScale(maximum, level) {
    return 1 + (Math.max(1, maximum) - 1) * clamp(level, 0, 1);
}

// Each image stays inside its fixed slot horizontally. No neighbour offsets
// or changing anchor: only upward growth for a bottom dock.
export function boundedScale(scale, imageExtent, slotExtent) {
    if (imageExtent <= 0 || slotExtent <= 0) return 1;
    return clamp(scale, 1, Math.max(1, (slotExtent - 2) / imageExtent));
}

// The transformed visual grows equally from both sides of its allocation.
// Keeping this calculation separate makes the hit area match the actual
// painted extent instead of an arbitrary oversized box.
export function iconOverflow(iconSize, scale) {
    return Math.max(0, iconSize * (Math.max(1, scale) - 1) / 2);
}

export function pointInExpandedBox(box, x, y, isHorizontal, padding) {
    if (isHorizontal) {
        return x >= box.x1 && x <= box.x2 &&
            y >= box.y1 - padding && y <= box.y2 + padding;
    }

    return y >= box.y1 && y <= box.y2 &&
        x >= box.x1 - padding && x <= box.x2 + padding;
}

// Exponential smoothing is independent of frame rate: a 60 Hz and a 144 Hz
// display converge with the same visual response time.
export function settleToward(current, target, elapsedMs, responseMs) {
    if (responseMs <= 0 || elapsedMs <= 0)
        return elapsedMs <= 0 ? current : target;

    const progress = 1 - Math.exp(-elapsedMs / responseMs);
    return current + (target - current) * progress;
}

// extraExtents contain the visual width/height added by magnification. The
// selected icon remains anchored; every neighbour moves just enough to retain
// its gap with the next enlarged icon.
export function distributeOffsets(extraExtents, anchorIndex) {
    const offsets = new Array(extraExtents.length).fill(0);
    if (anchorIndex < 0 || anchorIndex >= extraExtents.length)
        return offsets;

    for (let index = anchorIndex - 1; index >= 0; index--) {
        offsets[index] = offsets[index + 1] -
            (extraExtents[index] + extraExtents[index + 1]) / 2;
    }
    for (let index = anchorIndex + 1; index < extraExtents.length; index++) {
        offsets[index] = offsets[index - 1] +
            (extraExtents[index] + extraExtents[index - 1]) / 2;
    }
    return offsets;
}
DOCK_FILE_custom_effects_magnification_math_js_END

# ARCHIVO: custom-effects/magnification.js
mkdir -p -- "$stage/"'custom-effects'
cat > "$stage/"'custom-effects/magnification.js' <<'DOCK_FILE_custom_effects_magnification_js_END'
// Ampliación de iconos estilo macOS para GNOME Shell (v7: lente continua).
//
// Cada icono se amplía según su distancia al cursor y se desplaza hacia fuera
// con la integral de la ampliación (lens-math.js): el dock se ensancha, el
// icono bajo el cursor permanece bajo el cursor y no hay saltos al pasar de uno
// a otro. Solo se transforma la imagen (_iconBin): insignias, indicadores y
// zonas de clic conservan su tamaño. El estante de vidrio crece con el dock.

import {Clutter, GLib, Meta, St} from '../dependencies/gi.js';
import {getCursorTracker} from '../utils.js';
import {selectVisualActor} from './actor-selection.js';
import {
    clamp,
    iconOverflow,
    magnificationLevel,
    magnifiedScale,
    settleToward,
} from './magnification-math.js';
import {lensOffset} from './lens-math.js';

const ACTIVATION_PADDING = 24;
const INFLUENCE_RADIUS_ICONS = 2.6;
const SCALE_EPSILON = 0.002;
const OFFSET_EPSILON = 0.05;

export class MagnificationController {
    constructor(dash, settings) {
        this._dash = dash;
        this._settings = settings;
        this._box = dash._box;
        this._isHorizontal = dash._isHorizontal;
        this._position = dash._position;
        this._pointer = null;
        this._states = new Map();
        this._shelf = {a: 0, b: 0};
        this._configuredActors = new WeakSet();
        this._laterId = 0;
        this._lastFrameUs = 0;
        this._settingIds = [];

        this._cursorTracker = getCursorTracker();
        this._cursorId = this._cursorTracker.connect('position-invalidated',
            () => this._updatePointerPosition());
        for (const key of ['magnify-icons', 'magnification-max-scale', 'magnification-response-ms']) {
            this._settingIds.push(settings.connect(`changed::${key}`,
                () => this._onSettingsChanged()));
        }
        this._updatePointerPosition();
    }

    destroy() {
        this._stopFrames();
        this._resetImmediately();
        this._cursorTracker.disconnect(this._cursorId);
        for (const id of this._settingIds)
            this._settings.disconnect(id);
        this._settingIds = [];
        this._states.clear();
        this._box = null;
        this._cursorTracker = null;
        this._settings = null;
        this._dash = null;
    }

    _enabled() {
        return this._settings.get_boolean('magnify-icons');
    }

    _maximumScale() {
        return clamp(this._settings.get_double('magnification-max-scale'), 1, 2);
    }

    _responseMs() {
        return clamp(this._settings.get_int('magnification-response-ms'), 40, 220);
    }

    _radius() {
        return this._dash.iconSize * INFLUENCE_RADIUS_ICONS;
    }

    _onSettingsChanged() {
        if (!this._enabled())
            this._pointer = null;
        this._startFrames();
    }

    // ── Cursor ────────────────────────────────────────────────────────
    _updatePointerPosition() {
        if (!this._enabled()) {
            if (this._pointer !== null) {
                this._pointer = null;
                this._startFrames();
            }
            return;
        }

        const [sx, sy] = global.get_pointer();
        const pointer = this._isInside(sx, sy) ? (this._isHorizontal ? sx : sy) : null;
        if (pointer !== this._pointer) {
            this._pointer = pointer;
            this._startFrames();
        }
    }

    _isInside(sx, sy) {
        const c = this._dash._dashContainer;
        if (!c?.get_stage() || !c.mapped)
            return false;

        const [x, y] = c.get_transformed_position();
        const [w, h] = c.get_transformed_size();
        const maximum = this._maximumScale();
        const along = (maximum - 1) * this._radius() / 2 + 4;
        const across = iconOverflow(this._dash.iconSize, maximum) + ACTIVATION_PADDING;
        const p = this._position;
        const before = (p === St.Side.BOTTOM || p === St.Side.RIGHT) ? across : 4;
        const after = (p === St.Side.TOP || p === St.Side.LEFT) ? across : 4;

        if (this._isHorizontal) {
            return sx >= x - along && sx <= x + w + along &&
                sy >= y - before && sy <= y + h + after;
        }
        return sy >= y - along && sy <= y + h + along &&
            sx >= x - before && sx <= x + w + after;
    }

    // ── Bucle de cuadros sincronizado con el compositor ───────────────
    _startFrames() {
        if (this._laterId)
            return;
        this._laterId = global.compositor.get_laters().add(
            Meta.LaterType.BEFORE_REDRAW, () => {
                const animating = this._updateFrame();
                if (!animating) {
                    this._laterId = 0;
                    return GLib.SOURCE_REMOVE;
                }
                return GLib.SOURCE_CONTINUE;
            });
    }

    _stopFrames() {
        if (!this._laterId)
            return;
        global.compositor.get_laters().remove(this._laterId);
        this._laterId = 0;
    }

    _items() {
        const list = [];
        const horizontal = this._isHorizontal;
        const push = (container, visual, scalable) => {
            if (!visual || !container?.get_stage())
                return;
            if (scalable)
                this._configureIconActor(visual);
            const [x, y] = container.get_transformed_position();
            const [w, h] = container.get_transformed_size();
            const start = horizontal ? x : y;
            const extent = horizontal ? w : h;
            list.push({
                actor: visual, scalable,
                start, end: start + extent, center: start + extent / 2,
            });
        };

        for (const item of this._box.get_children())
            push(item, selectVisualActor(item.child?._delegate), true);

        const showApps = this._dash._showAppsIcon;
        if (showApps?.visible)
            push(showApps, selectVisualActor(showApps), true);

        for (const sep of [this._dash._separator, this._dash._locSeparator])
            push(sep, sep, false);

        return list;
    }

    _configureIconActor(actor) {
        if (this._configuredActors.has(actor))
            return;

        actor.set_content_scaling_filters(
            Clutter.ScalingFilter.TRILINEAR,
            Clutter.ScalingFilter.TRILINEAR);
        const firstChild = actor.get_child?.() ?? actor.get_first_child?.();
        firstChild?.set_content_scaling_filters(
            Clutter.ScalingFilter.TRILINEAR,
            Clutter.ScalingFilter.TRILINEAR);
        this._configuredActors.add(actor);
    }

    _updateFrame() {
        const now = GLib.get_monotonic_time();
        const elapsedMs = this._lastFrameUs ? (now - this._lastFrameUs) / 1000 : 1000 / 60;
        this._lastFrameUs = now;

        const items = this._items();
        const pointer = this._pointer;
        const active = this._enabled() && pointer !== null && items.length > 0;
        const maximum = this._maximumScale();
        const radius = this._radius();
        const present = new Set();
        let unsettled = false;

        for (const item of items) {
            present.add(item.actor);
            let scale = 1;
            let offset = 0;
            if (active) {
                if (item.scalable) {
                    scale = magnifiedScale(maximum,
                        magnificationLevel(Math.abs(pointer - item.center), radius));
                }
                offset = lensOffset(item.center, pointer, radius, maximum);
            }
            unsettled = this._applyState(item.actor, scale, offset, elapsedMs) || unsettled;
        }

        let a = 0;
        let b = 0;
        if (active) {
            a = lensOffset(Math.min(...items.map(i => i.start)), pointer, radius, maximum);
            b = lensOffset(Math.max(...items.map(i => i.end)), pointer, radius, maximum);
        }
        unsettled = this._applyShelf(a, b, elapsedMs) || unsettled;

        for (const [actor] of this._states) {
            if (!present.has(actor))
                this._states.delete(actor);
        }

        if (!unsettled)
            this._lastFrameUs = 0;
        return unsettled;
    }

    _applyState(actor, targetScale, targetOffset, elapsedMs) {
        const state = this._states.get(actor) ?? {scale: 1, offset: 0};
        const responseMs = this._responseMs();
        const nextScale = settleToward(state.scale, targetScale, elapsedMs, responseMs);
        const nextOffset = settleToward(state.offset, targetOffset, elapsedMs, responseMs);
        const settled = Math.abs(nextScale - targetScale) <= SCALE_EPSILON &&
            Math.abs(nextOffset - targetOffset) <= OFFSET_EPSILON;
        const scale = settled ? targetScale : nextScale;
        const offset = settled ? targetOffset : nextOffset;
        const [pivotX, pivotY] = this._pivot();

        actor.set_pivot_point(pivotX, pivotY);
        actor.scale_x = scale;
        actor.scale_y = scale;
        // El eje transversal queda libre para el rebote de lanzamiento.
        if (this._isHorizontal)
            actor.translation_x = offset;
        else
            actor.translation_y = offset;

        this._states.set(actor, {scale, offset});
        return !settled;
    }

    // El estante crece lo mismo que el icono de cada extremo se desplaza.
    _applyShelf(targetA, targetB, elapsedMs) {
        const s = this._shelf;
        const responseMs = this._responseMs();
        s.a = settleToward(s.a, targetA, elapsedMs, responseMs);
        s.b = settleToward(s.b, targetB, elapsedMs, responseMs);
        const settled = Math.abs(s.a - targetA) <= OFFSET_EPSILON &&
            Math.abs(s.b - targetB) <= OFFSET_EPSILON;
        if (settled) {
            s.a = targetA;
            s.b = targetB;
        }
        this._writeShelf(s.a, s.b);
        return !settled;
    }

    _writeShelf(a, b) {
        const bg = this._dash?._background;
        if (bg) {
            const size = this._isHorizontal ? bg.get_width() : bg.get_height();
            const k = size > 0 ? (size + (b - a)) / size : 1;
            if (this._isHorizontal) {
                bg.set_pivot_point(0, 0.5);
                bg.scale_x = k;
                bg.translation_x = a;
            } else {
                bg.set_pivot_point(0.5, 0);
                bg.scale_y = k;
                bg.translation_y = a;
            }
        }
        this._dash?._glassShelf?.setStretch(a, b);
    }

    _pivot() {
        switch (this._position) {
        case St.Side.BOTTOM: return [0.5, 1];
        case St.Side.TOP: return [0.5, 0];
        case St.Side.LEFT: return [0, 0.5];
        case St.Side.RIGHT: return [1, 0.5];
        default: return [0.5, 0.5];
        }
    }

    _resetImmediately() {
        for (const [actor] of this._states) {
            actor.scale_x = 1;
            actor.scale_y = 1;
            if (this._isHorizontal)
                actor.translation_x = 0;
            else
                actor.translation_y = 0;
        }
        this._shelf = {a: 0, b: 0};
        this._writeShelf(0, 0);
    }
}
DOCK_FILE_custom_effects_magnification_js_END

# ARCHIVO: custom-effects/overflow-policy.js
mkdir -p -- "$stage/"'custom-effects'
cat > "$stage/"'custom-effects/overflow-policy.js' <<'DOCK_FILE_custom_effects_overflow_policy_js_END'
const FULLY_SHOWN_EPSILON = 0.001;

/**
 * The slide container only needs a clip while the dock is moving through the
 * screen edge. Once fully shown, clipping would cut transformed icon content.
 *
 * @param {number} slideProgress value from 0 (hidden) to 1 (shown)
 * @returns {boolean} whether the slide viewport must clip its child
 */
export function shouldClipSlideContainer(slideProgress) {
    return slideProgress < 1 - FULLY_SHOWN_EPSILON;
}
DOCK_FILE_custom_effects_overflow_policy_js_END

# ARCHIVO: custom-effects/README.md
mkdir -p -- "$stage/"'custom-effects'
cat > "$stage/"'custom-effects/README.md' <<'DOCK_FILE_custom_effects_README_md_END'
# Efectos propios de macOS 27

Este directorio contiene únicamente código nuevo de la personalización.
No se modifican archivos de Dash to Dock hasta que cada efecto tenga una prueba
aislada y una ruta de desactivación.

Componentes:

1. `magnification-math.js`: curva de proximidad pura y testeable.
2. `actor-selection.js`: selecciona únicamente `_iconBin`. Las insignias,
   números, indicadores y resaltados mantienen su tamaño nativo.
3. `magnification.js`: seguimiento global del cursor y ampliación sincronizada
   con el compositor sin modificar el layout ni las zonas de clic del dock.

Dash to Dock conserva su estructura raíz porque sus módulos se importan entre
sí con rutas relativas. Sus funciones nativas de ventanas, favoritos,
accesibilidad y monitores no se reemplazan.

Corrección 24/10/2026: posiciones fijas, sin redistribución de vecinos al
cambiar de icono. La ampliación se limita al ancho disponible de cada celda
y se ancla abajo en el dock inferior. Se corrigen las coordenadas locales de
activación y el primer paso de animación para evitar un salto inicial.

Pruebas: `gjs -m tests/magnification-test.js`,
`node tests/glass-style-test.mjs` y `bash tests/smoke-magnification.sh`.
La última crea un GNOME aislado, comprueba límites, pivote y retorno al tamaño
original, y guarda una captura; no activa modo inseguro en la sesión habitual.
DOCK_FILE_custom_effects_README_md_END

# ARCHIVO: custom-effects/shelf.js
mkdir -p -- "$stage/"'custom-effects'
cat > "$stage/"'custom-effects/shelf.js' <<'DOCK_FILE_custom_effects_shelf_js_END'
// Estante de vidrio del dock (macOS 27): desenfoque real del fondo + estilo CSS.
//
// El desenfoque de Shell es rectangular; se recorta por dentro del radio de las
// esquinas (inset ≈ 0,3 × radio) para que nunca asome fuera del borde redondeado.

import {Clutter, Shell, St} from '../dependencies/gi.js';

export class GlassShelf {
    constructor(dash, settings) {
        this._dash = dash;
        this._settings = settings;
        this._inset = 8;
        this._a = 0;
        this._b = 0;
        this._ids = [];

        const bg = dash._background;
        this.blur = new St.Widget({
            name: 'dashtodockGlassBlur', reactive: false,
            style: 'background-color: rgba(0, 0, 0, 0.004);',
        });
        const bind = (coordinate, offset) => {
            const c = new Clutter.BindConstraint({source: bg, coordinate, offset});
            this.blur.add_constraint(c);
            return c;
        };
        this._cx = bind(Clutter.BindCoordinate.X, this._inset);
        this._cy = bind(Clutter.BindCoordinate.Y, this._inset);
        this._cw = bind(Clutter.BindCoordinate.WIDTH, -2 * this._inset);
        this._ch = bind(Clutter.BindCoordinate.HEIGHT, -2 * this._inset);
        dash.insert_child_below(this.blur, bg);

        for (const key of ['glass-shelf', 'glass-blur'])
            this._ids.push(settings.connect(`changed::${key}`, () => this._sync()));
        this._styleId = bg.connect('style-changed', () => this._syncInset());
        this._sync();
    }

    destroy() {
        for (const id of this._ids)
            this._settings.disconnect(id);
        this._ids = [];
        const bg = this._dash._background;
        if (bg && this._styleId)
            bg.disconnect(this._styleId);
        this._styleId = 0;
        this._dash.remove_style_class_name('mac-shelf');
        this.blur.clear_effects();
        this.blur.destroy();
        this.blur = null;
    }

    // Estiramiento del estante cuando el dock se ensancha (ver magnification.js).
    setStretch(a, b) {
        this._a = a;
        this._b = b;
        this._applyOffsets();
    }

    _applyOffsets() {
        const horizontal = this._dash._isHorizontal;
        const i = this._inset;
        const grow = this._b - this._a;
        this._cx.offset = i + (horizontal ? this._a : 0);
        this._cy.offset = i + (horizontal ? 0 : this._a);
        this._cw.offset = -2 * i + (horizontal ? grow : 0);
        this._ch.offset = -2 * i + (horizontal ? 0 : grow);
    }

    _syncInset() {
        try {
            const r = this._dash._background.get_theme_node().get_border_radius(St.Corner.TOPLEFT);
            const inset = Math.ceil(r * 0.3) + 1;
            if (inset !== this._inset && inset >= 0 && inset < 40) {
                this._inset = inset;
                this._applyOffsets();
            }
        } catch (_e) {
            // se conserva el valor anterior
        }
    }

    _sync() {
        const enabled = this._settings.get_boolean('glass-shelf');
        if (enabled)
            this._dash.add_style_class_name('mac-shelf');
        else
            this._dash.remove_style_class_name('mac-shelf');

        this.blur.clear_effects();
        const strength = this._settings.get_int('glass-blur');
        this.blur.visible = enabled && strength > 0;
        if (!this.blur.visible)
            return;
        try {
            const fx = new Shell.BlurEffect({mode: Shell.BlurMode.BACKGROUND});
            const sigma = Math.max(2, strength);
            if ('sigma' in fx)
                fx.sigma = sigma;
            else if ('radius' in fx)
                fx.radius = sigma * 2;
            fx.brightness = 0.96;
            this.blur.add_effect(fx);
        } catch (e) {
            console.error(`[Dock macOS 27] desenfoque no disponible: ${e.message}`);
        }
    }
}
DOCK_FILE_custom_effects_shelf_js_END

# ARCHIVO: dash.js
mkdir -p -- "$stage/"'.'
cat > "$stage/"'dash.js' <<'DOCK_FILE_dash_js_END'
// -*- mode: js; js-indent-level: 4; indent-tabs-mode: nil -*-

import {
    Clutter,
    Gio,
    GLib,
    GObject,
    Shell,
    St,
} from './dependencies/gi.js';

import {
    AppFavorites,
    Dash,
    DND,
    Main,
} from './dependencies/shell/ui.js';

import {
    Config,
    Util,
} from './dependencies/shell/misc.js';

import {
    AppIcons,
    Docking,
    Theming,
    Utils,
} from './imports.js';

import {MagnificationController} from './custom-effects/magnification.js';
import {GlassShelf} from './custom-effects/shelf.js'; // macos27-v7:import

// module "Dash" did not export DASH_ANIMATION_TIME in old versions
// so we just define it like it is defined in Dash;
// taken from https://gitlab.gnome.org/GNOME/gnome-shell/-/blob/main/js/ui/dash.js
const DASH_ANIMATION_TIME = Dash.DASH_ANIMATION_TIME ?? 200;
const DASH_VISIBILITY_TIMEOUT = 3;

const Labels = Object.freeze({
    SHOW_MOUNTS: Symbol('show-mounts'),
    FIRST_LAST_CHILD_WORKAROUND: Symbol('first-last-child-workaround'),
});

/**
 * Extend DashItemContainer
 *
 * - set label position based on dash orientation
 *
 */
const DockDashItemContainer = GObject.registerClass(
class DockDashItemContainer extends Dash.DashItemContainer {
    _init(position) {
        super._init();

        if (position === St.Side.TOP || position === St.Side.BOTTOM)
            this.xExpand = false;
        else
            this.yExpand = false;

        this.label?.add_style_class_name(Theming.PositionStyleClass[position]);
        if (Docking.DockManager.settings.customThemeShrink)
            this.label?.add_style_class_name('shrink');
    }

    showLabel() {
        return AppIcons.itemShowLabel.call(this);
    }

    // we override the method show taken from:
    // https://gitlab.gnome.org/GNOME/gnome-shell/-/blob/main/js/ui/dash.js
    // in order to apply a little modification at the end of the animation
    // which makes sure that the icon background is not blurry
    show(animate) {
        if (this.child == null)
            return;

        this.ease({
            scale_x: 1,
            scale_y: 1,
            opacity: 255,
            duration: animate ? DASH_ANIMATION_TIME : 0,
            mode: Clutter.AnimationMode.EASE_OUT_QUAD,
            onComplete: () => {
                // when the animation is ended, we simulate
                // a hover to gain back focus and unblur the
                // background
                this.set_hover(true);
            },
        });
    }
});

const DockDashIconsVerticalLayout = GObject.registerClass(
    class DockDashIconsVerticalLayout extends Clutter.BoxLayout {
        _init() {
            super._init({
                orientation: Clutter.Orientation.VERTICAL,
            });
        }

        vfunc_get_preferred_height(container, forWidth) {
            const [natHeight] = super.vfunc_get_preferred_height(container, forWidth);
            return [natHeight, 0];
        }
    });


const baseIconSizes = [16, 22, 24, 32, 48, 64, 96, 128];

/**
 * This class is a fork of the upstream dash class (ui.dash.js)
 *
 * Summary of changes:
 * - disconnect global signals adding a destroy method;
 * - play animations even when not in overview mode
 * - set a maximum icon size
 * - show running and/or favorite applications
 * - hide showApps label when the custom menu is shown.
 * - add scrollview
 *   ensure actor is visible on keyfocus inseid the scrollview
 * - add 128px icon size, might be useful for hidpi display
 * - sync minimization application target position.
 * - keep running apps ordered.
 */
export const DockDash = GObject.registerClass({
    Properties: {
        'requires-visibility': GObject.ParamSpec.boolean(
            'requires-visibility', 'requires-visibility', 'requires-visibility',
            GObject.ParamFlags.READWRITE,
            false),
        'max-width': GObject.ParamSpec.int(
            'max-width', 'max-width', 'max-width',
            GObject.ParamFlags.READWRITE,
            -1, GLib.MAXINT32, -1),
        'max-height': GObject.ParamSpec.int(
            'max-height', 'max-height', 'max-height',
            GObject.ParamFlags.READWRITE,
            -1, GLib.MAXINT32, -1),
    },
    Signals: {
        'menu-opened': {},
        'menu-closed': {},
        'icon-size-changed': {},
    },
}, class DockDash extends St.Widget {
    _init(monitorIndex) {
        // Initialize icon variables and size
        super._init({
            name: 'dash',
            layout_manager: new Clutter.BinLayout(),
        });

        this._maxWidth = -1;
        this._maxHeight = -1;
        this.iconSize = Docking.DockManager.settings.dashMaxIconSize;
        this._availableIconSizes = baseIconSizes;
        this._shownInitially = false;
        this._initializeIconSize(this.iconSize);
        this._signalsHandler = new Utils.GlobalSignalsHandler(this);

        this._separator = null;

        this._monitorIndex = monitorIndex;
        this._position = Utils.getPosition();
        this._isHorizontal = (this._position === St.Side.TOP) ||
                               (this._position === St.Side.BOTTOM);

        this._dragPlaceholder = null;
        this._dragPlaceholderPos = -1;
        this._animatingPlaceholdersCount = 0;
        this._showLabelTimeoutId = 0;
        this._resetHoverTimeoutId = 0;
        this._labelShowing = false;

        this._dashContainer = new St.BoxLayout({
            name: 'dashtodockDashContainer',
            x_align: Clutter.ActorAlign.CENTER,
            y_align: Clutter.ActorAlign.CENTER,
            y_expand: this._isHorizontal,
            x_expand: !this._isHorizontal,
        });

        this._scrollView = new St.ScrollView({
            name: 'dashtodockDashScrollview',
            hscrollbar_policy: this._isHorizontal ? St.PolicyType.EXTERNAL : St.PolicyType.NEVER,
            vscrollbar_policy: this._isHorizontal ?  St.PolicyType.NEVER : St.PolicyType.EXTERNAL,
            x_expand: this._isHorizontal,
            y_expand: !this._isHorizontal,
            enable_mouse_scrolling: false,
        });

        this._scrollView.connect('scroll-event', this._onScrollEvent.bind(this));
        // macos27-v7:clip - los iconos ampliados no se recortan en el visor.
        this._scrollView.clip_to_allocation = false;

        this._boxContainer = new St.BoxLayout({
            name: 'dashtodockBoxContainer',
            // St.BoxLayout derives from St.Viewport. Its default clip-to-view
            // framebuffer clip would cut magnified icons at the dock edge.
            clip_to_view: false,
            x_align: Clutter.ActorAlign.FILL,
            y_align: Clutter.ActorAlign.FILL,
        });
        this._boxContainer.add_style_class_name(Theming.PositionStyleClass[this._position]);

        const rtl = Clutter.get_default_text_direction() === Clutter.TextDirection.RTL;
        this._box = new St.BoxLayout({
            clip_to_allocation: false,
            ...!this._isHorizontal ? {layout_manager: new DockDashIconsVerticalLayout()} : {},
            x_align: rtl ? Clutter.ActorAlign.END : Clutter.ActorAlign.START,
            y_align: this._isHorizontal ? Clutter.ActorAlign.CENTER : Clutter.ActorAlign.START,
            y_expand: !this._isHorizontal,
            x_expand: this._isHorizontal,
        });

        if (this._dashContainer.orientation !== undefined) {
            this._dashContainer.orientation =
                this._boxContainer.orientation =
                this._box.orientation = this._isHorizontal
                    ? Clutter.Orientation.HORIZONTAL
                    : Clutter.Orientation.VERTICAL;
        } else {
            this._dashContainer.vertical =
                this._boxContainer.vertical =
                this._box.vertical = !this._isHorizontal;
        }

        this._box._delegate = this;
        this._boxContainer.add_child(this._box);
        this._magnification = new MagnificationController(
            this, Docking.DockManager.settings);
        Utils.addActor(this._scrollView, this._boxContainer);
        this._dashContainer.add_child(this._scrollView);

        this._showAppsIcon = new AppIcons.DockShowAppsIcon(this._position);
        this._showAppsIcon.show(false);
        this._showAppsIcon.icon.setIconSize(this.iconSize);
        this._showAppsIcon.x_expand = false;
        this._showAppsIcon.y_expand = false;
        this.showAppsButton.connect('notify::hover', a => {
            if (this._showAppsIcon.get_parent() === this._boxContainer)
                this._ensureItemVisibility(a);
        });
        if (!this._isHorizontal)
            this._showAppsIcon.y_align = Clutter.ActorAlign.START;
        this._hookUpLabel(this._showAppsIcon);
        this._showAppsIcon.connect('menu-state-changed', (_icon, opened) => {
            this._itemMenuStateChanged(this._showAppsIcon, opened);
        });
        this.updateShowAppsButton();

        this._background = new St.Widget({
            style_class: 'dash-background',
            y_expand: this._isHorizontal,
            x_expand: !this._isHorizontal,
        });

        const sizerBox = new Clutter.Actor();
        sizerBox.add_constraint(new Clutter.BindConstraint({
            source: this._isHorizontal ? this._showAppsIcon.icon : this._dashContainer,
            coordinate: Clutter.BindCoordinate.HEIGHT,
        }));
        sizerBox.add_constraint(new Clutter.BindConstraint({
            source: this._isHorizontal ? this._dashContainer : this._showAppsIcon.icon,
            coordinate: Clutter.BindCoordinate.WIDTH,
        }));
        this._background.add_child(sizerBox);

        this.add_child(this._background);
        this.add_child(this._dashContainer);

        // macos27-v7:shelf - estante de vidrio con desenfoque real.
        this._glassShelf = new GlassShelf(this, Docking.DockManager.settings);

        this._workId = Main.initializeDeferredWork(this._box, () => this._redisplay());

        this._shellSettings = new Gio.Settings({
            schema_id: 'org.gnome.shell',
        });

        this._appSystem = Shell.AppSystem.get_default();

        this.iconAnimator = new Docking.IconAnimator(this);

        this._signalsHandler.add([
            this._appSystem,
            'installed-changed',
            () => {
                AppFavorites.getAppFavorites().reload();
                this._queueRedisplay();
            },
        ], [
            AppFavorites.getAppFavorites(),
            'changed',
            this._queueRedisplay.bind(this),
        ], [
            this._appSystem,
            'app-state-changed',
            this._queueRedisplay.bind(this),
        ], [
            Main.overview,
            'item-drag-begin',
            this._onItemDragBegin.bind(this),
        ], [
            Main.overview,
            'item-drag-end',
            this._onItemDragEnd.bind(this),
        ], [
            Main.overview,
            'item-drag-cancelled',
            this._onItemDragCancelled.bind(this),
        ], [
            Main.overview,
            'window-drag-begin',
            this._onWindowDragBegin.bind(this),
        ], [
            Main.overview,
            'window-drag-cancelled',
            this._onWindowDragEnd.bind(this),
        ], [
            Main.overview,
            'window-drag-end',
            this._onWindowDragEnd.bind(this),
        ]);

        this.connect('destroy', this._onDestroy.bind(this));
    }

    vfunc_get_preferred_height(forWidth) {
        const [minHeight, natHeight] = super.vfunc_get_preferred_height.call(this, forWidth);
        if (!this._isHorizontal && this._maxHeight !== -1 && natHeight > this._maxHeight)
            return [minHeight, this._maxHeight];
        else
            return [minHeight, natHeight];
    }

    vfunc_get_preferred_width(forHeight) {
        const [minWidth, natWidth] = super.vfunc_get_preferred_width.call(this, forHeight);
        if (this._isHorizontal && this._maxWidth !== -1 && natWidth > this._maxWidth)
            return [minWidth, this._maxWidth];
        else
            return [minWidth, natWidth];
    }

    get _container() {
        return this._dashContainer;
    }

    _onDestroy() {
        this._magnification.destroy();
        this._magnification = null;
        // macos27-v7:shelf-destroy
        this._glassShelf?.destroy();
        this._glassShelf = null;
        if (this._resetHoverTimeoutId) {
            GLib.source_remove(this._resetHoverTimeoutId);
            this._resetHoverTimeoutId = 0;
        }
        this.iconAnimator.destroy();

        if (this._requiresVisibilityTimeout) {
            GLib.source_remove(this._requiresVisibilityTimeout);
            delete this._requiresVisibilityTimeout;
        }

        if (this._ensureActorVisibilityTimeoutId) {
            GLib.source_remove(this._ensureActorVisibilityTimeoutId);
            delete this._ensureActorVisibilityTimeoutId;
        }

        if (this._showLabelTimeoutId) {
            GLib.source_remove(this._showLabelTimeoutId);
            this._showLabelTimeoutId = 0;
        }
    }


    _onItemDragBegin(...args) {
        return Dash.Dash.prototype._onItemDragBegin.call(this, ...args);
    }

    _onItemDragCancelled(...args) {
        return Dash.Dash.prototype._onItemDragCancelled.call(this, ...args);
    }

    _onItemDragEnd(...args) {
        return Dash.Dash.prototype._onItemDragEnd.call(this, ...args);
    }

    _endItemDrag(...args) {
        return Dash.Dash.prototype._endItemDrag.call(this, ...args);
    }

    _onItemDragMotion(...args) {
        return Dash.Dash.prototype._onItemDragMotion.call(this, ...args);
    }

    _appIdListToHash(...args) {
        return Dash.Dash.prototype._appIdListToHash.call(this, ...args);
    }

    _queueRedisplay(...args) {
        return Dash.Dash.prototype._queueRedisplay.call(this, ...args);
    }

    _hookUpLabel(...args) {
        return Dash.Dash.prototype._hookUpLabel.call(this, ...args);
    }

    // macos27-v7:label - etiqueta casi inmediata, como en macOS.
    _syncLabel(item, appIcon) {
        const shouldShow = appIcon
            ? appIcon.shouldShowTooltip() : item.child.get_hover();

        if (shouldShow) {
            if (this._showLabelTimeoutId === 0) {
                const timeout = this._labelShowing ? 0 : 70;
                this._showLabelTimeoutId = GLib.timeout_add(
                    GLib.PRIORITY_DEFAULT, timeout, () => {
                        this._labelShowing = true;
                        item.showLabel();
                        this._showLabelTimeoutId = 0;
                        return GLib.SOURCE_REMOVE;
                    });
                if (this._resetHoverTimeoutId > 0) {
                    GLib.source_remove(this._resetHoverTimeoutId);
                    this._resetHoverTimeoutId = 0;
                }
            }
        } else {
            if (this._showLabelTimeoutId > 0)
                GLib.source_remove(this._showLabelTimeoutId);
            this._showLabelTimeoutId = 0;
            item.hideLabel();
            if (this._labelShowing) {
                this._resetHoverTimeoutId = GLib.timeout_add(
                    GLib.PRIORITY_DEFAULT, 250, () => {
                        this._labelShowing = false;
                        this._resetHoverTimeoutId = 0;
                        return GLib.SOURCE_REMOVE;
                    });
            }
        }
    }

    // macos27-v7:locsep - separador entre las apps y la papelera/volúmenes.
    _updateLocationSeparator() {
        const children = this._box.get_children();
        const appOf = actor => actor.child?.app ?? actor.child?._delegate?.app;
        const first = children.findIndex(actor => {
            const app = appOf(actor);
            return !!app && (app.isTrash || !!app.location) && !actor.animatingOut;
        });
        const hasAppsBefore = first > 0 && children.slice(0, first).some(a => !!appOf(a));
        const alreadySeparated = first > 0 && children[first - 1] === this._separator;

        if (!hasAppsBefore || alreadySeparated) {
            this._locSeparator?.destroy();
            this._locSeparator = null;
            return;
        }

        if (!this._locSeparator) {
            this._locSeparator = new St.Widget({
                style_class: 'dash-separator',
                x_align: this._isHorizontal
                    ? Clutter.ActorAlign.FILL : Clutter.ActorAlign.CENTER,
                y_align: this._isHorizontal
                    ? Clutter.ActorAlign.CENTER : Clutter.ActorAlign.FILL,
            });
        }
        this._locSeparator.set_size(
            this._isHorizontal ? -1 : this.iconSize,
            this._isHorizontal ? this.iconSize : -1);
        this._locSeparator.get_parent()?.remove_child(this._locSeparator);
        this._box.insert_child_at_index(this._locSeparator, first);
    }

    _clearDragPlaceholder(...args) {
        return Dash.Dash.prototype._clearDragPlaceholder.call(this, ...args);
    }

    _clearEmptyDropTarget(...args) {
        return Dash.Dash.prototype._clearEmptyDropTarget.call(this, ...args);
    }

    handleDragOver(source, actor, x, y, time) {
        let ret;
        if (this._isHorizontal) {
            ret = Dash.Dash.prototype.handleDragOver.call(this, source, actor, x, y, time);

            if (ret === DND.DragMotionResult.CONTINUE)
                return ret;
        } else {
            const propertyInjections = new Utils.PropertyInjectionsHandler();
            propertyInjections.add(this._box, 'width', {
                get: () => this._box.get_children().reduce((a, c) => a + c.height, 0),
            });

            if (this._dragPlaceholder) {
                propertyInjections.add(this._dragPlaceholder, 'width', {
                    get: () => this._dragPlaceholder.height,
                });
            }

            ret = Dash.Dash.prototype.handleDragOver.call(this, source, actor, y, x, time);
            propertyInjections.destroy();

            if (ret === DND.DragMotionResult.CONTINUE)
                return ret;

            if (this._dragPlaceholder) {
                this._dragPlaceholder.child.set_width(this.iconSize / 2);
                this._dragPlaceholder.child.set_height(this.iconSize);

                let pos = this._dragPlaceholderPos;
                if (this._isHorizontal &&
                    Clutter.get_default_text_direction() === Clutter.TextDirection.RTL)
                    pos = this._box.get_children() - 1 - pos;

                if (pos !== this._dragPlaceholderPos) {
                    this._dragPlaceholderPos = pos;
                    this._box.set_child_at_index(this._dragPlaceholder,
                        this._dragPlaceholderPos);
                }
            }
        }

        if (this._dragPlaceholder) {
            // Ensure the next and previous icon are visible when moving the
            // placeholder (we're assuming there's room for both of them)
            const children = this._box.get_children();
            if (this._dragPlaceholderPos > 0) {
                ensureActorVisibleInScrollView(this._scrollView,
                    children[this._dragPlaceholderPos - 1]);
            }

            if (this._dragPlaceholderPos >= -1 &&
                this._dragPlaceholderPos < children.length - 1) {
                ensureActorVisibleInScrollView(this._scrollView,
                    children[this._dragPlaceholderPos + 1]);
            }
        }

        return ret;
    }

    acceptDrop(...args) {
        return Dash.Dash.prototype.acceptDrop.call(this, ...args);
    }

    _onWindowDragBegin(...args) {
        return Dash.Dash.prototype._onWindowDragBegin.call(this, ...args);
    }

    _onWindowDragEnd(...args) {
        return Dash.Dash.prototype._onWindowDragEnd.call(this, ...args);
    }

    _onScrollEvent(actor, event) {
        // If scroll is not used because the icon is resized, let the scroll event propagate.
        if (!Docking.DockManager.settings.iconSizeFixed)
            return Clutter.EVENT_PROPAGATE;

        // reset timeout to avid conflicts with the mousehover event
        this._ensureItemVisibility(null);

        // Skip to avoid double events mouse
        if (event.get_scroll_direction() !== Clutter.ScrollDirection.SMOOTH)
            return Clutter.EVENT_STOP;


        let adjustment, delta = 0;

        if (this._isHorizontal) {
            adjustment = this._scrollView.get_hadjustment
                ? this._scrollView.get_hadjustment()
                : this._scrollView.get_hscroll_bar().get_adjustment();
        } else {
            adjustment = this._scrollView.get_vadjustment
                ? this._scrollView.get_vadjustment()
                : this._scrollView.get_vscroll_bar().get_adjustment();
        }

        const increment = adjustment.step_increment;
        const [dx, dy] = event.get_scroll_delta();

        if (this._isHorizontal)
            delta = (Math.abs(dx) > Math.abs(dy) ? dx : dy) * increment;
        else
            delta = dy * increment;

        const value = adjustment.get_value();

        // TODO: Remove this if possible.
        if (Number.isNaN(value))
            adjustment.set_value(delta);
        else
            adjustment.set_value(value + delta);

        return Clutter.EVENT_STOP;
    }

    _ensureItemVisibility(actor) {
        if (actor?.hover) {
            const destroyId =
                actor.connect('destroy', () => this._ensureItemVisibility(null));
            this._ensureActorVisibilityTimeoutId = GLib.timeout_add(
                GLib.PRIORITY_DEFAULT, 100, () => {
                    actor.disconnect(destroyId);
                    ensureActorVisibleInScrollView(this._scrollView, actor);
                    this._ensureActorVisibilityTimeoutId = 0;
                    return GLib.SOURCE_REMOVE;
                });
        } else if (this._ensureActorVisibilityTimeoutId) {
            GLib.source_remove(this._ensureActorVisibilityTimeoutId);
            this._ensureActorVisibilityTimeoutId = 0;
        }
    }

    _createAppItem(app) {
        const appIcon = new AppIcons.makeAppIcon(app, this._monitorIndex, this.iconAnimator);

        if (appIcon._draggable) {
            appIcon._draggable.connect('drag-begin', () => {
                appIcon.opacity = 50;
            });
            appIcon._draggable.connect('drag-end', () => {
                appIcon.opacity = 255;
            });
        }

        appIcon.connectObject('menu-state-changed', (_, opened) => {
            this._itemMenuStateChanged(item, opened);
        }, this);

        const item = new DockDashItemContainer(this._position);
        item.setChild(appIcon);

        appIcon.connectObject('notify::hover', a => this._ensureItemVisibility(a), this);
        appIcon.connectObject('clicked', actor => {
            ensureActorVisibleInScrollView(this._scrollView, actor);
        }, this);

        appIcon.connectObject('key-focus-in', actor => {
            const [xShift, yShift] = ensureActorVisibleInScrollView(this._scrollView, actor);

            // This signal is triggered also by mouse click. The popup menu is opened at the original
            // coordinates. Thus correct for the shift which is going to be applied to the scrollview.
            if (appIcon._menu) {
                appIcon._menu._boxPointer.xOffset = -xShift;
                appIcon._menu._boxPointer.yOffset = -yShift;
            }
        }, this);

        appIcon.connectObject('notify::focused', () => {
            const {settings} = Docking.DockManager;
            if (appIcon.focused && settings.scrollToFocusedApplication)
                ensureActorVisibleInScrollView(this._scrollView, item);
        }, this);

        appIcon.connectObject('notify::urgent', () => {
            if (appIcon.urgent) {
                ensureActorVisibleInScrollView(this._scrollView, item);
                if (Docking.DockManager.settings.showDockUrgentNotify)
                    this._requireVisibility();
            }
        }, this);

        // Override default AppIcon labelActor, now the
        // accessibleName is set at DashItemContainer.setLabelText
        appIcon.labelActor = null;
        item.setLabelText(app.get_name());

        appIcon.icon.setIconSize(this.iconSize);
        this._hookUpLabel(item, appIcon);

        item.connectObject('notify::position', () => appIcon.updateIconGeometry(), appIcon);
        item.connectObject('notify::size', () => appIcon.updateIconGeometry(), appIcon);

        return item;
    }

    _requireVisibility() {
        this.requiresVisibility = true;

        if (this._requiresVisibilityTimeout)
            GLib.source_remove(this._requiresVisibilityTimeout);

        this._requiresVisibilityTimeout = GLib.timeout_add_seconds(GLib.PRIORITY_DEFAULT,
            DASH_VISIBILITY_TIMEOUT, () => {
                this._requiresVisibilityTimeout = 0;
                this.requiresVisibility = false;
            });
    }

    /**
     * Return an array with the "proper" appIcons currently in the dash
     */
    getAppIcons() {
        // Only consider children which are "proper"
        // icons (i.e. ignoring drag placeholders) and which are not
        // animating out (which means they will be destroyed at the end of
        // the animation)
        const iconChildren = this._box.get_children().filter(actor => {
            return actor.child &&
                   !!actor.child.icon &&
                   !actor.animatingOut;
        });

        const appIcons = iconChildren.map(actor => {
            return actor.child;
        });

        return appIcons;
    }

    _itemMenuStateChanged(item, opened) {
        Dash.Dash.prototype._itemMenuStateChanged.call(this, item, opened);

        if (opened) {
            this.emit('menu-opened');
        } else {
            // I want to listen from outside when a menu is closed. I used to
            // add a custom signal to the appIcon, since gnome 3.8 the signal
            // calling this callback was added upstream.
            this.emit('menu-closed');
        }
    }

    _adjustIconSize() {
        // For the icon size, we only consider children which are "proper"
        // icons (i.e. ignoring drag placeholders) and which are not
        // animating out (which means they will be destroyed at the end of
        // the animation)
        const iconChildren = this._box.get_children().filter(actor => {
            return actor.child &&
                   actor.child._delegate &&
                   actor.child._delegate.icon &&
                   !actor.animatingOut;
        });

        iconChildren.push(this._showAppsIcon);

        if (this._maxWidth === -1 && this._maxHeight === -1)
            return;

        // Check if the container is present in the stage. This avoids critical
        // errors when unlocking the screen
        if (!this._container.get_stage())
            return;

        const themeNode = this._dashContainer.get_theme_node();
        const maxAllocation = new Clutter.ActorBox({
            x1: 0,
            y1: 0,
            x2: this._isHorizontal ? this._maxWidth : 42 /* whatever */,
            y2: this._isHorizontal ? 42 : this._maxHeight,
        });
        const maxContent = themeNode.get_content_box(maxAllocation);
        let availSpace;
        if (this._isHorizontal)
            availSpace = maxContent.get_width();
        else
            availSpace = maxContent.get_height();

        const spacing = themeNode.get_length('spacing');

        const [{child: firstButton}] = iconChildren;
        const {child: firstIcon} = firstButton?.icon ?? {child: null};

        // if no icons there's nothing to adjust
        if (!firstIcon)
            return;

        // Enforce valid spacings during the size request
        firstIcon.ensure_style();
        const [, , iconWidth, iconHeight] = firstIcon.get_preferred_size();
        const [, , buttonWidth, buttonHeight] = firstButton.get_preferred_size();

        if (this._isHorizontal) {
            // Subtract icon padding and box spacing from the available width
            availSpace -= iconChildren.length * (buttonWidth - iconWidth) +
                           (iconChildren.length - 1) * spacing;

            if (this._separator) {
                const [, , separatorWidth] = this._separator.get_preferred_size();
                availSpace -= separatorWidth + spacing;
            }
        } else {
            // Subtract icon padding and box spacing from the available height
            availSpace -= iconChildren.length * (buttonHeight - iconHeight) +
                           (iconChildren.length - 1) * spacing;

            if (this._separator) {
                const [, , , separatorHeight] = this._separator.get_preferred_size();
                availSpace -= separatorHeight + spacing;
            }
        }

        const maxIconSize = availSpace / iconChildren.length;
        const {scaleFactor} = St.ThemeContext.get_for_stage(global.stage);
        const iconSizes = this._availableIconSizes.map(s => s * scaleFactor);

        let [newIconSize] = this._availableIconSizes;
        for (let i = 0; i < iconSizes.length; i++) {
            if (iconSizes[i] <= maxIconSize)
                newIconSize = this._availableIconSizes[i];
        }

        if (newIconSize === this.iconSize)
            return;

        const oldIconSize = this.iconSize;
        this.iconSize = newIconSize;
        this.emit('icon-size-changed');

        const scale = oldIconSize / newIconSize;
        for (let i = 0; i < iconChildren.length; i++) {
            const {icon} = iconChildren[i].child._delegate;

            // Set the new size immediately, to keep the icons' sizes
            // in sync with this.iconSize
            icon.setIconSize(this.iconSize);

            // Don't animate the icon size change when the overview
            // is transitioning, not visible or when initially filling
            // the dash
            if (!Main.overview.visible || Main.overview.animationInProgress ||
                !this._shownInitially)
                continue;

            const [targetWidth, targetHeight] = icon.icon.get_size();

            // Scale the icon's texture to the previous size and
            // tween to the new size
            icon.icon.set_size(icon.icon.width * scale,
                icon.icon.height * scale);

            icon.icon.ease({
                width: targetWidth,
                height: targetHeight,
                duration: DASH_ANIMATION_TIME,
                mode: Clutter.AnimationMode.EASE_OUT_QUAD,
            });
        }

        if (this._separator) {
            const animateProperties = this._isHorizontal
                ? {height: this.iconSize} : {width: this.iconSize};

            this._separator.ease({
                ...animateProperties,
                duration: DASH_ANIMATION_TIME,
                mode: Clutter.AnimationMode.EASE_OUT_QUAD,
            });
        }
    }

    vfunc_map() {
        super.vfunc_map();
        this._queueRedisplay();
    }

    _redisplay() {
        if (!this.mapped)
            return;

        const favorites = AppFavorites.getAppFavorites().getFavoriteMap();

        let running = this._appSystem.get_running();
        const dockManager = Docking.DockManager.getDefault();
        const {settings} = dockManager;

        this._scrollView.set({
            xAlign: Clutter.ActorAlign.FILL,
            yAlign: Clutter.ActorAlign.FILL,
        });
        if (dockManager.settings.dockExtended) {
            if (!this._isHorizontal) {
                this._scrollView.yAlign = dockManager.settings.alwaysCenterIcons
                    ? Clutter.ActorAlign.CENTER : Clutter.ActorAlign.START;
            } else {
                this._scrollView.xAlign = dockManager.settings.alwaysCenterIcons
                    ? Clutter.ActorAlign.CENTER : Clutter.ActorAlign.START;
            }
        }

        if (settings.isolateWorkspaces ||
            settings.isolateMonitors) {
            // When using isolation, we filter out apps that have no windows in
            // the current workspace
            const monitorIndex = this._monitorIndex;
            running = running.filter(app =>
                AppIcons.getInterestingWindows(app.get_windows(), monitorIndex).length);
        }

        const children = this._box.get_children().filter(actor => {
            return actor.child &&
                   actor.child._delegate &&
                   actor.child._delegate.app;
        });
        // Apps currently in the dash
        let oldApps = children.map(actor => actor.child._delegate.app);
        // Apps supposed to be in the dash
        const newApps = [];

        const {showFavorites} = settings;
        if (showFavorites)
            newApps.push(...Object.values(favorites));

        if (settings.showRunning) {
            // We reorder the running apps so that they don't change position on the
            // dash with every redisplay() call

            // First: add the apps from the oldApps list that are still running
            oldApps.forEach(oldApp => {
                const index = running.indexOf(oldApp);
                if (index > -1) {
                    const [app] = running.splice(index, 1);
                    if (!showFavorites || !(app.get_id() in favorites))
                        newApps.push(app);
                }
            });

            // Second: add the new apps
            running.forEach(app => {
                if (!showFavorites || !(app.get_id() in favorites))
                    newApps.push(app);
            });
        }

        this._signalsHandler.removeWithLabel(Labels.SHOW_MOUNTS);
        if (dockManager.removables) {
            this._signalsHandler.addWithLabel(Labels.SHOW_MOUNTS,
                dockManager.removables, 'changed', this._queueRedisplay.bind(this));
            dockManager.removables.getApps().forEach(removable => {
                if (!newApps.includes(removable))
                    newApps.push(removable);
            });
        } else {
            oldApps = oldApps.filter(app => !app.location || app.isTrash);
        }

        if (dockManager.trash) {
            const trashApp = dockManager.trash.getApp();
            if (!newApps.includes(trashApp))
                newApps.push(trashApp);
        } else {
            oldApps = oldApps.filter(app => !app.isTrash);
        }

        // macos27-v7:locsep-remove
        this._locSeparator?.get_parent()?.remove_child(this._locSeparator);

        // Temporary remove the separator so that we don't compute to position icons
        const oldSeparatorPos = this._box.get_children().indexOf(this._separator);
        if (this._separator)
            this._box.remove_child(this._separator);

        // Figure out the actual changes to the list of items; we iterate
        // over both the list of items currently in the dash and the list
        // of items expected there, and collect additions and removals.
        // Moves are both an addition and a removal, where the order of
        // the operations depends on whether we encounter the position
        // where the item has been added first or the one from where it
        // was removed.
        // There is an assumption that only one item is moved at a given
        // time; when moving several items at once, everything will still
        // end up at the right position, but there might be additional
        // additions/removals (e.g. it might remove all the launchers
        // and add them back in the new order even if a smaller set of
        // additions and removals is possible).
        // If above assumptions turns out to be a problem, we might need
        // to use a more sophisticated algorithm, e.g. Longest Common
        // Subsequence as used by diff.

        const addedItems = [];
        const removedActors = [];

        let newIndex = 0;
        let oldIndex = 0;
        while (newIndex < newApps.length || oldIndex < oldApps.length) {
            const oldApp = oldApps.length > oldIndex ? oldApps[oldIndex] : null;
            const newApp = newApps.length > newIndex ? newApps[newIndex] : null;

            // No change at oldIndex/newIndex
            if (oldApp === newApp) {
                oldIndex++;
                newIndex++;
                continue;
            }

            // App removed at oldIndex
            if (oldApp && !newApps.includes(oldApp)) {
                removedActors.push(children[oldIndex]);
                oldIndex++;
                continue;
            }

            // App added at newIndex
            if (newApp && !oldApps.includes(newApp)) {
                addedItems.push({
                    app: newApp,
                    item: this._createAppItem(newApp),
                    pos: newIndex,
                });
                newIndex++;
                continue;
            }

            // App moved
            const nextApp = newApps.length > newIndex + 1
                ? newApps[newIndex + 1] : null;
            const insertHere = nextApp && nextApp === oldApp;
            const alreadyRemoved = removedActors.reduce((result, actor) => {
                const removedApp = actor.child._delegate.app;
                return result || removedApp === newApp;
            }, false);

            if (insertHere || alreadyRemoved) {
                const newItem = this._createAppItem(newApp);
                addedItems.push({
                    app: newApp,
                    item: newItem,
                    pos: newIndex + removedActors.length,
                });
                newIndex++;
            } else {
                removedActors.push(children[oldIndex]);
                oldIndex++;
            }
        }

        for (let i = 0; i < addedItems.length; i++) {
            this._box.insert_child_at_index(addedItems[i].item,
                addedItems[i].pos);
        }

        for (let i = 0; i < removedActors.length; i++) {
            const item = removedActors[i];

            // Don't animate item removal when the overview is transitioning
            // or hidden
            if (!Main.overview.animationInProgress)
                item.animateOutAndDestroy();
            else
                item.destroy();
        }

        // Update separator
        const nFavorites = Object.keys(favorites).length;
        const nIcons = children.length + addedItems.length - removedActors.length;
        if (nFavorites > 0 && nFavorites < nIcons) {
            if (!this._separator) {
                this._separator = new St.Widget({
                    style_class: 'dash-separator',
                    x_align: this._isHorizontal
                        ? Clutter.ActorAlign.FILL : Clutter.ActorAlign.CENTER,
                    y_align: this._isHorizontal
                        ? Clutter.ActorAlign.CENTER : Clutter.ActorAlign.FILL,
                    width: this._isHorizontal ? -1 : this.iconSize,
                    height: this._isHorizontal ? this.iconSize : -1,
                    reactive: true,
                    track_hover: true,
                });
                this._separator.connect('notify::hover', a => this._ensureItemVisibility(a));
            }
            let pos = nFavorites + this._animatingPlaceholdersCount;
            if (this._dragPlaceholder)
                pos++;
            const removedFavorites = removedActors.filter(a =>
                children.indexOf(a) < oldSeparatorPos);
            pos += removedFavorites.length;
            this._box.insert_child_at_index(this._separator, pos);
        } else if (this._separator) {
            this._separator.destroy();
            this._separator = null;
        }

        this._adjustIconSize();
        this._updateLocationSeparator(); // macos27-v7:locsep-update

        // Skip animations on first run when adding the initial set
        // of items, to avoid all items zooming in at once
        const animate = this._shownInitially &&
            !Main.layoutManager._startingUp;

        if (!this._shownInitially)
            this._shownInitially = true;

        addedItems.forEach(({item}) => item.show(animate));

        // This will update the size, and the corresponding number for each icon
        this._updateNumberOverlay();

        this.updateShowAppsButton();
    }

    _updateNumberOverlay() {
        const appIcons = this.getAppIcons();
        let counter = 1;
        appIcons.forEach(icon => {
            if (counter < 10) {
                icon.setNumberOverlay(counter);
                counter++;
            } else if (counter === 10) {
                icon.setNumberOverlay(0);
                counter++;
            } else {
                // No overlay after 10
                icon.setNumberOverlay(-1);
            }
            icon.updateNumberOverlay();
        });
    }

    toggleNumberOverlay(activate) {
        const appIcons = this.getAppIcons();
        appIcons.forEach(icon => {
            icon.toggleNumberOverlay(activate);
        });
    }

    _initializeIconSize(maxSize) {
        const maxAllowed = baseIconSizes[baseIconSizes.length - 1];
        maxSize = Math.min(maxSize, maxAllowed);

        if (Docking.DockManager.settings.iconSizeFixed) {
            this._availableIconSizes = [maxSize];
        } else {
            this._availableIconSizes = baseIconSizes.filter(val => {
                return val < maxSize;
            });
            this._availableIconSizes.push(maxSize);
        }
    }

    setIconSize(maxSize, doNotAnimate) {
        this._initializeIconSize(maxSize);

        if (doNotAnimate)
            this._shownInitially = false;

        this._queueRedisplay();
    }

    /**
     * Reset the displayed apps icon to maintain the correct order when changing
     * show favorites/show running settings
     */
    resetAppIcons() {
        const children = this._box.get_children().filter(actor => {
            return actor.child &&
                   !!actor.child.icon;
        });
        for (let i = 0; i < children.length; i++) {
            const item = children[i];
            item.destroy();
        }

        // to avoid ugly animations, just suppress them like when dash is first loaded.
        this._shownInitially = false;
        this._redisplay();
    }

    get showAppsButton() {
        return this._showAppsIcon.toggleButton;
    }

    showShowAppsButton() {
        this._showAppsIcon.visible = true;
        this._showAppsIcon.show(true);
        this.updateShowAppsButton();
    }

    hideShowAppsButton() {
        this._showAppsIcon.visible = false;
    }

    get maxWidth() {
        return this._maxWidth;
    }

    get maxHeight() {
        return this._maxHeight;
    }

    set maxWidth(maxWidth) {
        this.setMaxSize(maxWidth, this._maxHeight);
    }

    set maxHeight(maxHeight) {
        this.setMaxSize(this._maxWidth, maxHeight);
    }

    setMaxSize(maxWidth, maxHeight) {
        if (this._maxWidth === maxWidth &&
            this._maxHeight === maxHeight)
            return;

        this._maxWidth = maxWidth;
        this._maxHeight = maxHeight;
        this._queueRedisplay();
    }

    updateShowAppsButton() {
        if (this._showAppsIcon.get_parent() && !this._showAppsIcon.visible)
            return;

        const {settings} = Docking.DockManager;
        const notifiedProperties = [];
        const showAppsContainer = settings.showAppsAlwaysInTheEdge || !settings.dockExtended
            ? this._dashContainer : this._boxContainer;
        const needsFirstLastChildWorkaround = Config.PACKAGE_VERSION.split('.')[0] < 49;

        if (needsFirstLastChildWorkaround) {
            this._signalsHandler.addWithLabel(Labels.FIRST_LAST_CHILD_WORKAROUND,
                showAppsContainer, 'notify',
                (_obj, pspec) => notifiedProperties.push(pspec.name));
        }

        if (this._showAppsIcon.get_parent() !== showAppsContainer) {
            this._showAppsIcon.get_parent()?.remove_child(this._showAppsIcon);

            if (Docking.DockManager.settings.showAppsAtTop)
                showAppsContainer.insert_child_below(this._showAppsIcon, null);
            else
                showAppsContainer.insert_child_above(this._showAppsIcon, null);
        } else if (settings.showAppsAtTop) {
            showAppsContainer.set_child_below_sibling(this._showAppsIcon, null);
        } else {
            showAppsContainer.set_child_above_sibling(this._showAppsIcon, null);
        }

        if (needsFirstLastChildWorkaround) {
            this._signalsHandler.removeWithLabel(Labels.FIRST_LAST_CHILD_WORKAROUND);

            // This is indeed ugly, but we need to ensure that the last and first
            // visible widgets are re-computed by St, that is buggy because of a
            // mutter issue that is being fixed:
            // https://gitlab.gnome.org/GNOME/mutter/-/merge_requests/2047
            if (!notifiedProperties.includes('first-child'))
                showAppsContainer.notify('first-child');
            if (!notifiedProperties.includes('last-child'))
                showAppsContainer.notify('last-child');
        }
    }
});


/**
 * This is a copy of the same function in utils.js, but also adjust horizontal scrolling
 * and perform few further checks on the current value to avoid changing the values when
 * it would be clamp to the current one in any case.
 * Return the amount of shift applied
 *
 * @param scrollView
 * @param actor
 */
function ensureActorVisibleInScrollView(scrollView, actor) {
    // access to scrollView.[hv]scroll was deprecated in gnome 46
    // instead, adjustment can be accessed directly
    // keep old way for backwards compatibility (gnome <= 45)
    const vAdjustment = scrollView.vadjustment ?? scrollView.vscroll.adjustment;
    const hAdjustment = scrollView.hadjustment ?? scrollView.hscroll.adjustment;
    const {value: vValue0, pageSize: vPageSize, upper: vUpper} = vAdjustment;
    const {value: hValue0, pageSize: hPageSize, upper: hUpper} = hAdjustment;
    let [hValue, vValue] = [hValue0, vValue0];
    let vOffset = 0;
    let hOffset = 0;

    const fade = scrollView.get_effect('fade');
    if (fade) {
        vOffset = fade.fade_margins.top;
        hOffset = fade.fade_margins.left;
    }

    const box = actor.get_allocation_box();
    let {y1} = box, {y2} = box, {x1} = box, {x2} = box;

    let parent = actor.get_parent();
    while (parent !== scrollView) {
        if (!parent)
            throw new Error('Actor not in scroll view');

        const parentBox = parent.get_allocation_box();
        y1 += parentBox.y1;
        y2 += parentBox.y1;
        x1 += parentBox.x1;
        x2 += parentBox.x1;
        parent = parent.get_parent();
    }

    if (y1 < vValue + vOffset)
        vValue = Math.max(0, y1 - vOffset);
    else if (vValue < vUpper - vPageSize && y2 > vValue + vPageSize - vOffset)
        vValue = Math.min(vUpper - vPageSize, y2 + vOffset - vPageSize);

    if (x1 < hValue + hOffset)
        hValue = Math.max(0, x1 - hOffset);
    else if (hValue < hUpper - hPageSize && x2 > hValue + hPageSize - hOffset)
        hValue = Math.min(hUpper - hPageSize, x2 + hOffset - hPageSize);

    if (vValue !== vValue0) {
        vAdjustment.ease(vValue, {
            mode: Clutter.AnimationMode.EASE_OUT_QUAD,
            duration: Util.SCROLL_TIME,
        });
    }

    if (hValue !== hValue0) {
        hAdjustment.ease(hValue, {
            mode: Clutter.AnimationMode.EASE_OUT_QUAD,
            duration: Util.SCROLL_TIME,
        });
    }

    return [hValue - hValue0, vValue - vValue0];
}
DOCK_FILE_dash_js_END

# ARCHIVO: dbusmenuUtils.js
mkdir -p -- "$stage/"'.'
cat > "$stage/"'dbusmenuUtils.js' <<'DOCK_FILE_dbusmenuUtils_js_END'
// -*- mode: js; js-indent-level: 4; indent-tabs-mode: nil -*-

import {
    Atk,
    Clutter,
    Gio,
    GLib,
    St,
} from './dependencies/gi.js';

import {PopupMenu} from './dependencies/shell/ui.js';

import {Utils} from './imports.js';

// Dbusmenu features not (yet) supported:
//
//   * The CHILD_DISPLAY property
//
//     This seems to have only one possible value in the Dbusmenu API, so
//     there's little point in depending on it--the code in libdbusmenu sets it
//     if and only if an item has children, so for our purposes it's simpler
//     and more intuitive to just check children.length. (This does ignore the
//     possibility of a program not using libdbusmenu and setting CHILD_DISPLAY
//     independently, perhaps to indicate that an childless menu item should
//     nevertheless be displayed like a submenu.)
//
//   * Children more than two levels deep
//
//     PopupMenu doesn't seem to support submenus in submenus.
//
//   * Shortcut keys
//
//     If these keys are supposed to be installed as global shortcuts, we'd
//     have to query these aggressively and not wait for the DBus menu to be
//     mapped to a popup menu. A shortcut key that only works once the popup
//     menu is open and has key focus is possibly of marginal value.

/**
 *
 */
export async function haveDBusMenu() {
    try {
        const {default: DBusMenu} = await import('gi://Dbusmenu');
        return DBusMenu;
    } catch (e) {
        log(`Failed to import DBusMenu, quicklists are not available: ${e}`);
        return null;
    }
}

const DBusMenu = await haveDBusMenu();

/**
 * @param dbusmenuItem
 * @param deep
 */
export function makePopupMenuItem(dbusmenuItem, deep) {
    // These are the only properties guaranteed to be available when the root
    // item is first announced. Other properties might be loaded already, but
    // be sure to connect to Dbusmenu.MENUITEM_SIGNAL_PROPERTY_CHANGED to get
    // the most up-to-date values in case they aren't.
    const itemType = dbusmenuItem.property_get(DBusMenu.MENUITEM_PROP_TYPE);
    const label = dbusmenuItem.property_get(DBusMenu.MENUITEM_PROP_LABEL);
    const visible = dbusmenuItem.property_get_bool(DBusMenu.MENUITEM_PROP_VISIBLE);
    const enabled = dbusmenuItem.property_get_bool(DBusMenu.MENUITEM_PROP_ENABLED);
    const accessibleDesc = dbusmenuItem.property_get(DBusMenu.MENUITEM_PROP_ACCESSIBLE_DESC);
    // const childDisplay = dbusmenuItem.property_get(Dbusmenu.MENUITEM_PROP_CHILD_DISPLAY);

    let item;
    const signalsHandler = new Utils.GlobalSignalsHandler();
    const wantIcon = itemType === DBusMenu.CLIENT_TYPES_IMAGE;

    // If the basic type of the menu item needs to change, call this.
    const recreateItem = () => {
        const newItem = makePopupMenuItem(dbusmenuItem, deep);
        const parentMenu = item._parent;
        parentMenu.addMenuItem(newItem);
        // Reminder: Clutter thinks of later entries in the child list as
        // "above" earlier ones, so "above" here means "below" in terms of the
        // menu's vertical order.
        parentMenu.actor.set_child_above_sibling(newItem.actor, item.actor);
        if (newItem.menu)
            parentMenu.actor.set_child_above_sibling(newItem.menu.actor, newItem.actor);

        parentMenu.actor.remove_child(item.actor);
        item.destroy();
        item = null;
    };

    const updateDisposition = () => {
        const disposition = dbusmenuItem.property_get(DBusMenu.MENUITEM_PROP_DISPOSITION);
        let iconName = null;
        switch (disposition) {
        case DBusMenu.MENUITEM_DISPOSITION_ALERT:
        case DBusMenu.MENUITEM_DISPOSITION_WARNING:
            iconName = 'dialog-warning-symbolic';
            break;
        case DBusMenu.MENUITEM_DISPOSITION_INFORMATIVE:
            iconName = 'dialog-information-symbolic';
            break;
        }
        if (iconName) {
            item._dispositionIcon = new St.Icon({
                icon_name: iconName,
                style_class: 'popup-menu-icon',
                y_align: Clutter.ActorAlign.CENTER,
                y_expand: true,
            });
            let expander;
            for (let child = item.label.get_next_sibling(); ; child = child.get_next_sibling()) {
                if (!child) {
                    expander = new St.Bin({
                        style_class: 'popup-menu-item-expander',
                        x_expand: true,
                    });
                    item.actor.add_child(expander);
                    break;
                } else if (child instanceof St.Widget &&
                           child.has_style_class_name('popup-menu-item-expander')) {
                    expander = child;
                    break;
                }
            }
            item.actor.insert_child_above(item._dispositionIcon, expander);
        } else if (item._dispositionIcon) {
            item.actor.remove_child(item._dispositionIcon);
            item._dispositionIcon = null;
        }
    };

    const updateIcon = () => {
        if (!wantIcon)
            return;

        const iconData = dbusmenuItem.property_get_byte_array(DBusMenu.MENUITEM_PROP_ICON_DATA);
        const iconName = dbusmenuItem.property_get(DBusMenu.MENUITEM_PROP_ICON_NAME);
        if (iconName)
            item.icon.icon_name = iconName;
        else if (iconData.length)
            item.icon.gicon = Gio.BytesIcon.new(iconData);
    };

    const updateOrnament = () => {
        const toggleType = dbusmenuItem.property_get(DBusMenu.MENUITEM_PROP_TOGGLE_TYPE);
        switch (toggleType) {
        case DBusMenu.MENUITEM_TOGGLE_CHECK:
            item.actor.accessible_role = Atk.Role.CHECK_MENU_ITEM;
            break;
        case DBusMenu.MENUITEM_TOGGLE_RADIO:
            item.actor.accessible_role = Atk.Role.RADIO_MENU_ITEM;
            break;
        default:
            item.actor.accessible_role = Atk.Role.MENU_ITEM;
        }
        let ornament = PopupMenu.Ornament.NONE;
        const state = dbusmenuItem.property_get_int(DBusMenu.MENUITEM_PROP_TOGGLE_STATE);
        if (state === DBusMenu.MENUITEM_TOGGLE_STATE_UNKNOWN) {
            // PopupMenu doesn't natively support an "unknown" ornament, but we
            // can hack one in:
            item.setOrnament(ornament);
            item.actor.add_accessible_state(Atk.StateType.INDETERMINATE);
            item._ornamentLabel.text = '\u2501';
            item.actor.remove_style_pseudo_class('checked');
        } else {
            item.actor.remove_accessible_state(Atk.StateType.INDETERMINATE);
            if (state === DBusMenu.MENUITEM_TOGGLE_STATE_CHECKED) {
                if (toggleType === DBusMenu.MENUITEM_TOGGLE_CHECK)
                    ornament = PopupMenu.Ornament.CHECK;
                else if (toggleType === DBusMenu.MENUITEM_TOGGLE_RADIO)
                    ornament = PopupMenu.Ornament.DOT;

                item.actor.add_style_pseudo_class('checked');
            } else {
                item.actor.remove_style_pseudo_class('checked');
            }
            item.setOrnament(ornament);
        }
    };

    const onPropertyChanged = (_, name, value) => {
        // `value` is null when a property is cleared, so handle those cases
        // with sensible defaults.
        switch (name) {
        case DBusMenu.MENUITEM_PROP_TYPE:
            recreateItem();
            break;
        case DBusMenu.MENUITEM_PROP_ENABLED:
            item.setSensitive(value ? value.unpack() : false);
            break;
        case DBusMenu.MENUITEM_PROP_LABEL:
            item.label.text = value ? value.unpack() : '';
            break;
        case DBusMenu.MENUITEM_PROP_VISIBLE:
            item.actor.visible = value ? value.unpack() : false;
            break;
        case DBusMenu.MENUITEM_PROP_DISPOSITION:
            updateDisposition();
            break;
        case DBusMenu.MENUITEM_PROP_ACCESSIBLE_DESC:
            item.actor.get_accessible().accessible_description = value && value.unpack() || '';
            break;
        case DBusMenu.MENUITEM_PROP_ICON_DATA:
        case DBusMenu.MENUITEM_PROP_ICON_NAME:
            updateIcon();
            break;
        case DBusMenu.MENUITEM_PROP_TOGGLE_TYPE:
        case DBusMenu.MENUITEM_PROP_TOGGLE_STATE:
            updateOrnament();
            break;
        }
    };


    // Start actually building the menu item.
    const children = dbusmenuItem.get_children();
    if (children.length && !deep) {
        // Make a submenu.
        item = new PopupMenu.PopupSubMenuMenuItem(label, wantIcon);
        const updateChildren = () => {
            const itemChildren = dbusmenuItem.get_children();
            if (!itemChildren.length) {
                recreateItem();
                return;
            }

            item.menu.removeAll();
            itemChildren.forEach(remoteChild =>
                item.menu.addMenuItem(makePopupMenuItem(remoteChild, true)));
        };
        updateChildren();
        signalsHandler.add(
            [dbusmenuItem, DBusMenu.MENUITEM_SIGNAL_CHILD_ADDED, updateChildren],
            [dbusmenuItem, DBusMenu.MENUITEM_SIGNAL_CHILD_MOVED, updateChildren],
            [dbusmenuItem, DBusMenu.MENUITEM_SIGNAL_CHILD_REMOVED, updateChildren]);
    } else {
        // Don't make a submenu.
        if (!deep) {
            // We only have the potential to get a submenu if we aren't deep.
            signalsHandler.add(
                [dbusmenuItem, DBusMenu.MENUITEM_SIGNAL_CHILD_ADDED, recreateItem],
                [dbusmenuItem, DBusMenu.MENUITEM_SIGNAL_CHILD_MOVED, recreateItem],
                [dbusmenuItem, DBusMenu.MENUITEM_SIGNAL_CHILD_REMOVED, recreateItem]);
        }

        if (itemType === DBusMenu.CLIENT_TYPES_SEPARATOR) {
            item = new PopupMenu.PopupSeparatorMenuItem();
        } else if (wantIcon) {
            item = new PopupMenu.PopupImageMenuItem(label, null);
            item.icon = item._icon;
        } else {
            item = new PopupMenu.PopupMenuItem(label);
        }
    }

    // Set common initial properties.
    item.actor.visible = visible;
    item.setSensitive(enabled);
    if (accessibleDesc)
        item.actor.get_accessible().accessible_description = accessibleDesc;

    updateDisposition();
    updateIcon();
    updateOrnament();

    // Prevent an initial resize flicker.
    if (wantIcon)
        item.icon.icon_size = 16;


    signalsHandler.add(dbusmenuItem, DBusMenu.MENUITEM_SIGNAL_PROPERTY_CHANGED, onPropertyChanged);

    // Connections on item will be lost when item is disposed; there's no need
    // to add them to signalsHandler.
    item.connect('activate', () =>
        dbusmenuItem.handle_event(DBusMenu.MENUITEM_EVENT_ACTIVATED,
            new GLib.Variant('i', 0), Math.floor(Date.now() / 1000)));
    item.connect('destroy', () => signalsHandler.destroy());

    return item;
}
DOCK_FILE_dbusmenuUtils_js_END

